package com.rpb.reservation.workforce;
import static org.assertj.core.api.Assertions.*;
import static com.rpb.reservation.workforce.payroll.PayrollDtos.*;
import static com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.*;
import com.rpb.reservation.workforce.payroll.*;
import com.rpb.reservation.workforce.application.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;
class WorkforceCdacGovernancePostgresTest extends WorkforcePayChangePostgresTest {
 CdacBulkService bulk(){var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());return proxy(new CdacBulkService(access,new PayrollAccess(access,directory,jdbc),configs,repository,new PayrollRepository(jdbc,json),new CdacBulkRepository(jdbc,json),audit,json));}
 void seed(){var first=personal(0,"3000");var p=first.profile();var cpf=new com.rpb.reservation.workforce.statutory.StatutoryDtos.CpfProfile("citizen",LocalDate.of(1990,1,1),null,"GG","");approve(submit(changes.save(admin,store,UUID.randomUUID(),new Write(0L,company,employee,first.effectiveDate(),null,new ProfileWrite(0L,company,employee,first.effectiveDate(),p.templateId(),p.rule(),cpf,null,new CdacProfile("not_applicable","Explicit initial applicability declaration")),List.of(),null,"initial contract"))));}
 @Test void bulkSubmitsRequestInsteadOfWritingEffectiveCdacAndExactlyReplays(){seed();var service=bulk();var selection=new CdacBulk.Selection(company,"2026-12",List.of(employee),new CdacProfile("applicable","verified facts"));var preview=service.preview(admin,store,selection);var command=UUID.randomUUID();var write=new CdacBulk.Write(selection,preview.fingerprint(),"review eligibility change");var result=service.apply(admin,store,command,write);assertThat(result.profiles()).isEmpty();assertThat(result.requests()).hasSize(1);assertThat(result.requests().getFirst().status()).isEqualTo("submitted");assertThat(configs.profiles(tenant,company)).hasSize(1);assertThat(configs.profiles(tenant,company).getFirst().cdac().status()).isEqualTo("not_applicable");assertThat(service.apply(admin,store,command,write)).isEqualTo(result);assertThatThrownBy(()->service.apply(admin,store,command,new CdacBulk.Write(selection,preview.fingerprint(),"changed reason"))).hasMessage("WORKFORCE_CONFLICT");}
 @Test void bulkDoesNotMergeOrSubmitExistingRaiseDraft(){seed();var prior=configs.profiles(tenant,company).getFirst();var date=LocalDate.of(2026,12,1);var open=changes.save(admin,store,UUID.randomUUID(),new Write(0L,company,employee,date,null,new ProfileWrite(0L,company,employee,date,prior.templateId(),rule("4000"),prior.cpf()),List.of(),null,"unreviewed raise"));var service=bulk();var selection=new CdacBulk.Selection(company,"2026-12",List.of(employee),new CdacProfile("applicable","verified"));var result=service.apply(admin,store,UUID.randomUUID(),new CdacBulk.Write(selection,service.preview(admin,store,selection).fingerprint(),"CDAC only"));assertThat(result.requests().getFirst().status()).isEqualTo("failed");assertThat(result.requests().getFirst().error()).isEqualTo("WORKFORCE_CONFLICT");assertThat(changes.detail(admin,store,open.id()).status()).isEqualTo("draft");assertThat(changes.detail(admin,store,open.id()).content().profile().rule().rate()).isEqualTo("4000.00");}
 @Test void legacyExactCompletedCommandReplayNeedsNoNewReasonAndWritesNothing(){seed();var service=bulk();var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());var commands=new CdacBulkRepository(jdbc,json);var selection=new CdacBulk.Selection(company,"2026-12",List.of(employee),new CdacProfile("exempt","original legal evidence"));var preview=service.preview(admin,store,selection);UUID command=UUID.randomUUID();var write=new CdacBulk.Write(selection,preview.fingerprint());var original=new CdacBulk.Result(preview,List.of(configs.profiles(tenant,company).getFirst().id()));var mapper=new ObjectMapper().findAndRegisterModules();var oldPayload=(com.fasterxml.jackson.databind.node.ObjectNode)mapper.valueToTree(write);oldPayload.remove("reason");var oldResponse=(com.fasterxml.jackson.databind.node.ObjectNode)mapper.valueToTree(original);oldResponse.remove("requests");jdbc.update("insert into workforce_cdac_bulk_commands(id,tenant_id,company_id,store_id,actor_id,payload,response) values(?,?,?,?,?,?::jsonb,?::jsonb)",command,tenant,company,store,adminId,oldPayload.toString(),oldResponse.toString());
  var before=jdbc.queryForObject("select count(*) from workforce_pay_change_requests where tenant_id=?",Integer.class,tenant);assertThat(service.apply(admin,store,command,write)).isEqualTo(original);assertThat(jdbc.queryForObject("select count(*) from workforce_pay_change_requests where tenant_id=?",Integer.class,tenant)).isEqualTo(before);assertThat(jdbc.queryForObject("select count(*) from workforce_cdac_bulk_attempts where id=?",Integer.class,command)).isZero();assertThatThrownBy(()->service.apply(admin,store,UUID.randomUUID(),write)).hasMessage("WORKFORCE_INVALID");
 }
 @Test void sameProfileIdVersionChangeAfterPrepareIsStaleBeforeIndividualSubmission()throws Exception{
  seed();var service=bulk();var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());var commands=new CdacBulkRepository(jdbc,json);var selection=new CdacBulk.Selection(company,"2026-12",List.of(employee),new CdacProfile("applicable","Verified applicability"));var preview=service.preview(admin,store,selection);UUID command=UUID.randomUUID();var itemKey=UUID.nameUUIDFromBytes((command+":"+employee).getBytes(java.nio.charset.StandardCharsets.UTF_8));var held=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var holderPid=new java.util.concurrent.atomic.AtomicInteger();
  try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){
   var locker=pool.submit(()->commands.transaction().execute(status->{commands.lock(itemKey);holderPid.set(jdbc.queryForObject("select pg_backend_pid()",Integer.class));held.countDown();try{if(!release.await(25,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException("lock timeout");}catch(InterruptedException e){throw new IllegalStateException(e);}return true;}));
   try{assertThat(held.await(10,java.util.concurrent.TimeUnit.SECONDS)).isTrue();var running=pool.submit(()->service.apply(admin,store,command,new CdacBulk.Write(selection,preview.fingerprint(),"Previewed eligibility change")));boolean waiting=false;long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(15);
    while(System.nanoTime()<deadline){waiting=Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from pg_locks w join pg_locks h on w.locktype=h.locktype and w.classid=h.classid and w.objid=h.objid and w.objsubid=h.objsubid where h.pid=? and h.granted and not w.granted and w.locktype='advisory')",Boolean.class,holderPid.get()));if(waiting)break;Thread.sleep(25);}assertThat(waiting).as("bulk reached the individual lock only after validating the original full preview").isTrue();
    var old=configs.profiles(tenant,company).getFirst();approve(submit(changes.save(admin,store,UUID.randomUUID(),new Write(0L,company,employee,old.effectiveFrom(),null,new ProfileWrite(old.version(),company,employee,old.effectiveFrom(),old.templateId(),rule("4000"),old.cpf(),old.payment(),old.cdac()),List.of(),null,"Concurrent approved raise"))));release.countDown();assertThat(locker.get(10,java.util.concurrent.TimeUnit.SECONDS)).isTrue();var result=running.get(20,java.util.concurrent.TimeUnit.SECONDS);assertThat(result.requests().getFirst().status()).isEqualTo("stale");assertThat(result.requests().getFirst().error()).isEqualTo("WORKFORCE_CDAC_BULK_CHANGED");assertThat(jdbc.queryForObject("select count(*) from workforce_pay_change_requests where tenant_id=? and status='submitted'",Integer.class,tenant)).isZero();assertThat(configs.profiles(tenant,company).getFirst().rule().rate()).isEqualTo("4000.00");
   }finally{release.countDown();}
  }
 }
}
